import json

def load_episodes(path):
    with open(path) as f:
        return [json.loads(line) for line in f]

melt = load_episodes('/root/autodl-tmp/simgate-modular-routing/results/mvp/melt/episodes.jsonl')
change = load_episodes('/root/autodl-tmp/simgate-modular-routing/results/mvp/change-the-state-of-matter-of/episodes.jsonl')

print('=== ALL -100 EPISODES: TRIGGER ACTION ===')
for label, eps in [('melt', melt), ('change', change)]:
    print(f'\n--- {label} ---')
    for i, ep in enumerate(eps):
        ai = ep['always_internal']
        if ai['final_score'] == -100:
            # Find the step that caused -100
            trigger_step = None
            for s in ai['steps']:
                if s['score_delta'] == -100:
                    trigger_step = s
                    break
