                print(f'Ep {i} (var={ep[\"variation_idx\"]}): step {trigger_step[\"step\"]}/{ai[\"num_steps\"]}: \"{trigger_step[\"action\"]}\"')
            else:
                # Check last step
                last = ai['steps'][-1]
                print(f'Ep {i} (var={ep[\"variation_idx\"]}): no delta=-100 found, last action=\"{last[\"action\"]}\" score_after={last[\"score_after\"]}')

